{"candidate_skill": {"skill_id": "48fb9685-0b9c-5c1b-9f39-1b223c8f3098", "name": "Sensitive column removal with negated regex selection", "description": "Use qsv select with a negated regex selector to drop columns whose names match sensitive identifiers such as SSN, account number, or password before sharing or exporting data. Invoke when column headers reliably indicate PII or credentials and the output CSV will leave the cur...", "asset_type": "safety_rule", "granularity": "session", "asset_node_id": "safety_rule_node", "asset_level": 2, "objective": "Prevent disclosure of sensitive columns by excluding them from the selected output.", "domain": "qsv", "task_family": "privacy_guardrail", "method_family": "negated regex column exclusion", "stage": "pre-export de-identification", "workflow_steps": ["Identify the sensitive column names or a regex pattern that matches them, for example SSN, account_no, and password.", "Construct a single negated regex selector that matches those names, such as !/SSN|account_no|password/.", "Run qsv select with the negated selector against the input CSV, single-quoting the selector to protect it from shell interpretation.", "Inspect the output header: confirm no column matching the sensitive regex remains, and confirm that expected non-sensitive columns are still present.", "Proceed with sharing, publishing, or exporting the redacted CSV only after the header check passes."], "intervention_moves": ["Enumerate the sensitive column names or a regex pattern that matches them", "Build a negated regex selector in the form !/pattern/ that matches only those sensitive names", "Run qsv select with that selector on the input CSV", "Verify the resulting header omits every matching column and preserves the remaining columns", "Hand off the redacted CSV to the downstream sharing or export step"], "constraints": ["The selector must be a negated regex (!/pattern/) so non-matching columns are retained and matching columns are dropped.", "The regex is evaluated against column names, not cell values; it cannot detect sensitive content stored under unrelated headers.", "The selector should be single-quoted when passed through a shell so the pipe characters and other special characters are not interpreted by the shell.", "Verification of the emitted header is required before the output leaves the trust boundary."], "cautions": ["A negated regex drops only columns whose names match the pattern; misnamed, missing, or newly added sensitive columns will pass through unnoticed.", "If the pattern is too broad, legitimate columns may be dropped; if too narrow, sensitive columns may remain.", "Column names that look similar to sensitive identifiers can cause unintended removal, so the header check must confirm both exclusions and retentions.", "This move reduces disclosure risk for known named columns but does not guarantee full de-identification of the dataset."], "support_summary": {"support_count": 1, "conflict_count": 0, "support_sections": ["Examples [↩](#nav)"], "evidence_snippets": ["CONSTRAINT | Examples [↩](#nav): > Select the first and fourth columns ```console qsv select 1,4 ``` > Select the first 4 columns (by index) ```console qsv select 1-4 ``` > Select the first 4 columns (by name)..."]}}, "peer_candidates": [{"skill_id": "17a9578f-35d0-5b19-b47f-b2217f9caa5b", "name": "Column selector execution with qsv select", "description": "Use qsv select selector syntax to choose, order, or duplicate columns by 1-based index, header name, range, last-column token, or regex when a delimited file needs a precise column subset without changing row data.", "asset_type": "session_skill", "granularity": "session", "asset_node_id": "micro_skill_node", "asset_level": 3, "objective": "Produce a delimited output with the requested columns selected and ordered from an input delimited file, without changing row data.", "domain": "qsv", "task_family": "column_selection", "method_family": "qsv select selector syntax", "stage": "data preparation", "workflow_steps": ["Confirm which columns are requested and whether selection will use indices, header names, ranges, the last-column token _, or regex.", "Construct the selector using 1-based indices, ranges, header-name ranges, _ for the last column, and /regex/ for pattern matches.", "Repeat selectors to duplicate columns or reorder output arbitrarily.", "Quote header names or selectors that conflict with selector syntax or shell metacharacters.", "Run qsv select with the selector and input file.", "Inspect the output to confirm exactly the requested columns appear in the requested order and row data is unchanged."], "intervention_moves": ["Map requested columns to qsv select selector syntax", "Use 1-based indices, ranges, and header-name ranges", "Use _ for the last column and /regex/ for pattern-based selection", "Repeat selectors when duplicating columns", "Quote column names or selectors that conflict with selector syntax", "Execute qsv select and verify output column set and order"], "constraints": ["Assumes a delimited input with stable column order for index-based selectors and accessible header names for name-based or regex selectors.", "Selector syntax is 1-based and order-preserving by default; repeated columns are allowed.", "The output must preserve all row values; only columns are projected, reordered, or duplicated.", "Resolve missing or ambiguous target columns before execution instead of guessing."], "cautions": ["Regex selectors can match unintended columns; verify the output column set.", "Header-name ranges depend on current header ordering and may shift if upstream columns change.", "Do not use --random for this skill's deterministic selector-based output contract.", "This skill does not define row filtering, value transforms, joins, or aggregations."]}, {"skill_id": "01638e2d-c300-51b8-957f-544a62b88ee0", "name": "Column order sorting and seeded randomization", "description": "Apply qsv select --sort to order selected columns lexicographically by byte value, or --random with an optional --seed to reproducibly shuffle already-selected columns. Use when column membership is already determined and only column order needs deterministic or reproducible p...", "asset_type": "micro_skill", "granularity": "micro", "asset_node_id": "micro_skill_node", "asset_level": 3, "objective": "Reorder selected columns deterministically or pseudo-randomly while preserving row data.", "domain": "qsv", "task_family": "column_layout_control", "method_family": "qsv select --sort / --random --seed", "stage": "output preparation", "workflow_steps": ["Confirm the column selection expression is already defined.", "Choose --sort for lexicographic byte-order and deterministic output.", "Or choose --random for pseudo-random column order.", "If reproducibility is required, add --seed with a fixed value.", "Run qsv select with the selector plus the ordering flag and pass the resulting CSV to downstream processing."], "intervention_moves": ["Use --sort to order selected columns lexicographically by byte value", "Use --random to shuffle selected columns", "Use --random --seed <value> to produce the same shuffled column order across runs", "Combine --sort or --random with existing selector syntax such as 1-, 1,4,5-7"], "constraints": ["Only column order should change; selected columns and row data must be preserved.", "--random without a seed is not reproducible.", "--sort orders columns lexicographically by byte value."], "cautions": ["Seeded randomization is reproducibility-oriented, not cryptographic.", "Use column ordering flags on top of an explicit selection expression rather than as a substitute for selecting columns."]}], "existing_skills": []}

